 .bs-main.bs-clean-page .bs-ui-card > .bs-ui-card-title{font-size:clamp(20px,5.4vw,23px)}
}
@media(prefers-reduced-motion:reduce){
 .bs-main.bs-clean-page .bs-ui-card .bs-icon-card-watermark{transition:none}
}

