/* Connected trade flow replaces the three oversized/empty cards. */
.bs-stack-flow-section{background:#fff}
.bs-stack-flow-section .bs-ui-heading{margin-bottom:28px}
.bs-stack-flow-panel{
 position:relative;
 overflow:hidden;
 border:1px solid #d7e2ca;
 border-radius:22px;
 background:linear-gradient(125deg,#f1f7e8,#f8fbf4 62%,#eef5df);
 padding:clamp(20px,3vw,36px);
}
.bs-stack-flow-panel-top{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;margin-bottom:29px;color:#567628;font:800 11px/1.5 Inter,system-ui,sans-serif;letter-spacing:.11em}
.bs-stack-flow-emphasis{display:inline-flex;align-items:center;gap:8px;color:#41593a;font:600 12px/1.4 Inter,system-ui,sans-serif;letter-spacing:normal}
.bs-stack-flow-steps{margin:0;padding:0;display:flex;align-items:stretch;justify-content:space-between;list-style:none;gap:0}
.bs-stack-flow-item{min-width:0;display:flex;align-items:center;flex:1 1 0}
.bs-stack-flow-item:last-child{flex:0.85 1 0}
.bs-stack-flow-node{width:100%;min-height:172px;border-radius:15px;border:1px solid #d9e5d2;background:#fff;padding:20px 13px;display:flex;align-items:flex-start;flex-direction:column;justify-content:center;gap:6px;min-width:0;box-shadow:0 6px 18px rgba(27,47,16,.035)}
.bs-stack-flow-node-icon{width:43px;height:43px;border-radius:11px;background:#d8e9a2;color:#141613;display:grid;place-items:center;margin-bottom:9px}
.bs-stack-flow-node strong{font:700 clamp(13px,1.15vw,16px)/1.35 Manrope,Inter,system-ui,sans-serif;letter-spacing:-.02em;color:#161816;overflow-wrap:anywhere}
.bs-stack-flow-node > span:last-child{font:400 12px/1.5 Inter,system-ui,sans-serif;color:#52614f}
.bs-stack-flow-arrow{flex:0 0 clamp(22px,3vw,47px);height:24px;display:grid;place-items:center;color:#63852d}
.bs-stack-flow-caption{font:500 12px/1.55 Inter,system-ui,sans-serif;color:#52614f;margin:21px 0 0}
.bs-stack-flow-explanation{display:flex;flex-wrap:wrap;align-items:stretch;gap:20px;margin-top:22px}
.bs-stack-flow-prose{flex:1.5 1 480px;min-width:0}
.bs-stack-flow-prose p{font:400 15px/1.8 Inter,system-ui,sans-serif;color:#4c5c53;margin:0}
.bs-stack-flow-conclusion{flex:1 1 330px;display:flex;align-items:flex-start;gap:14px;padding:20px 23px;border:1px solid #d9e5ca;border-radius:16px;background:#f4f8ec;color:#314b1d}
.bs-stack-flow-conclusion svg{flex:0 0 22px;color:#617e30}
