 .bs-stack-flow-item,.bs-stack-flow-item:last-child{flex:1 1 auto;min-width:0}
 .bs-stack-flow-node{min-height:0;flex-direction:row;justify-content:flex-start;align-items:center;flex-wrap:wrap;gap:8px 12px;padding:14px}
 .bs-stack-flow-node-icon{margin:0;flex:0 0 42px}
