/* Viewport-anchored site review UI: scroll only fields, not the dialog header/action. */
.bs-review-trigger{
 position:fixed;right:0;top:50%;transform:translateY(-50%);z-index:90;
 display:inline-flex;gap:9px;align-items:center;justify-content:center;
 min-width:48px;min-height:48px;padding:12px 16px;
 border:1px solid #d3e1b9;border-radius:14px 0 0 14px;
 background:#d8e9a2;color:#172118;font:700 12px/1.25 Inter,system-ui,sans-serif;
 box-shadow:0 9px 30px rgba(21,38,16,.16);cursor:pointer;
 transition:background-color .2s ease;
}
.bs-review-trigger:hover{background:#c6dd90}
.bs-review-trigger:focus-visible{outline:3px solid #50702d;outline-offset:-3px}
.bs-review-backdrop{
 position:fixed;inset:0;z-index:120;display:flex;justify-content:flex-end;
 align-items:center;overscroll-behavior:contain;
 background:rgba(9,17,9,.66);padding:clamp(12px,2.5vw,28px);
}
.bs-review-dialog{
 box-sizing:border-box;display:flex;flex-direction:column;min-width:0;
 width:min(100%,490px);max-height:calc(100dvh - 28px);
 border:1px solid #dce6d0;border-radius:20px;background:#fff;
 box-shadow:0 20px 60px rgba(0,0,0,.24);overflow:hidden;color:#172118;
}
.bs-review-head{
 flex:0 0 auto;display:flex;align-items:flex-start;justify-content:space-between;
 gap:10px;padding:23px 25px 15px;border-bottom:1px solid #eef2e8;background:#fff;
}
.bs-review-kicker{display:block;font:800 10px/1.35 Inter,system-ui,sans-serif;letter-spacing:.12em;color:#637d2b;margin:0 0 7px}
.bs-review-head h2{font:700 clamp(22px,2.4vw,28px)/1.16 Manrope,Inter,system-ui,sans-serif;letter-spacing:-.04em;color:#161816;margin:0}
.bs-review-close{
 display:grid;place-items:center;flex:0 0 44px;width:44px;height:44px;
 border:1px solid #dce5d7;border-radius:12px;background:#f6f8f3;color:#253823;cursor:pointer;
}
.bs-review-body{
 flex:1 1 auto;min-height:0;overflow-y:auto;overflow-x:hidden;
 padding:19px 25px 20px;overscroll-behavior:contain;scrollbar-gutter:stable;
}
.bs-review-desc{font:400 14px/1.55 Inter,system-ui,sans-serif;color:#4c5c53;margin:0 0 16px}
.bs-review-privacy{
 display:flex;align-items:flex-start;gap:9px;margin:0 0 17px;padding:11px;
 border-radius:10px;background:#f3f7e9;color:#40543b;font:500 12px/1.5 Inter,system-ui,sans-serif;
}
.bs-review-privacy svg{flex:0 0 17px;margin-top:1px}
.bs-review-form,.bs-review-form label{display:flex;flex-direction:column;gap:7px}
.bs-review-form{gap:14px}
.bs-review-form label{min-width:0;color:#33452f;font:650 12px/1.35 Inter,system-ui,sans-serif}
.bs-review-two{display:flex;flex-wrap:wrap;gap:12px}
.bs-review-two label{flex:1 1 170px}
.bs-review-form input,.bs-review-form select,.bs-review-form textarea{
 box-sizing:border-box;width:100%;min-width:0;min-height:44px;border:1px solid #d7e0d1;
 border-radius:10px;padding:10px 12px;background:#fff;color:#1a2818;
 font:400 16px/1.35 Inter,system-ui,sans-serif;
}
.bs-review-form input[readonly]{background:#f5f8f2}
.bs-review-form textarea{min-height:96px;resize:vertical}
.bs-review-form input:focus-visible,.bs-review-form select:focus-visible,.bs-review-form textarea:focus-visible{
 outline:2px solid #70943a;outline-offset:1px;
}
.bs-review-footer{
 flex:0 0 auto;display:flex;flex-direction:column;gap:9px;
 padding:13px 25px max(16px,env(safe-area-inset-bottom));
 border-top:1px solid #e7ecdf;background:#fff;
}
.bs-review-submit{
 display:flex;align-items:center;justify-content:center;gap:11px;
 width:100%;min-height:48px;padding:11px 17px;
 border:none;border-radius:12px;background:#1b281c;color:#fff;
 font:750 14px/1.2 Inter,system-ui,sans-serif;cursor:pointer;
}
.bs-review-submit:hover{background:#324b2a}
.bs-review-submit:disabled{opacity:.55;cursor:wait}
.bs-review-status{
 margin:0;padding:10px 12px;border-radius:9px;
 font:500 12px/1.45 Inter,system-ui,sans-serif;
}
.bs-review-status.success{color:#285222;background:#edf7e7}
.bs-review-status.warning{color:#614211;background:#fff4de}
.bs-review-issue-link{
 display:inline-flex;align-items:center;justify-content:center;gap:8px;
 font:700 13px/1.35 Inter,system-ui,sans-serif;color:#314f23;
 min-height:36px;text-decoration:underline;
}
.bs-review-note{font:400 11px/1.4 Inter,system-ui,sans-serif;color:#667361;margin:0}
.bs-review-honeypot{position:absolute!important;left:-200vw!important;width:1px!important;height:1px!important;overflow:hidden!important}
.bs-review-close:focus-visible,.bs-review-submit:focus-visible,.bs-review-issue-link:focus-visible{
 outline:3px solid #70943a;outline-offset:2px;
}
@media(max-width:650px){
 .bs-review-trigger{padding:11px;right:0;border-radius:12px 0 0 12px}
 .bs-review-trigger span{display:none}
 .bs-review-backdrop{padding:0;align-items:flex-end}
 .bs-review-dialog{
  width:100%;height:auto;max-height:calc(100dvh - 13px);
  border-radius:19px 19px 0 0;border-bottom:0;
 }
 .bs-review-head{padding:15px 17px 12px;align-items:center}
 .bs-review-head h2{font-size:23px}
 .bs-review-body{padding:14px 17px 12px;scrollbar-gutter:auto}
 .bs-review-desc{margin-bottom:12px;font-size:13px}
 .bs-review-form{gap:11px}
 .bs-review-two{gap:10px}
 .bs-review-form label{flex-basis:100%}
 .bs-review-form input,.bs-review-form select,.bs-review-form textarea{font-size:16px}
 .bs-review-footer{padding:11px 17px max(12px,env(safe-area-inset-bottom))}
 .bs-review-note{font-size:10px}
}
@media(max-height:550px) {
 .bs-review-head{padding-block:10px}
 .bs-review-body{padding-block:10px}
 .bs-review-footer{padding-top:9px}
 .bs-review-note{display:none}
}
@media(prefers-reduced-motion:reduce){.bs-review-trigger{transition:none}}

component-sources.component:
'use client';

import {useCallback,useEffect,useRef,useState} from 'react';
import {ChevronLeft,ChevronRight} from 'lucide-react';
import {IconCard} from './IconCard';
import {SectionHeading} from './SectionHeading';

export type AudienceItem={title:string;description:string;icon:string};
type Props={title:string;kicker?:string;items:AudienceItem[]};

/**
 * Multi-card, responsive, circular carousel. Source copy remains in pages.content.json.
 * Three copies let the last-to-first transition move forward without a visual jump.
 */
export function AudienceCarousel({title,kicker='FOREX TRADE TECHNOLOGY',items}:Props){
 const count=items.length;
 const [position,setPosition]=useState(count);
 const [step,setStep]=useState(0);
 const [animate,setAnimate]=useState(false);
 const [interacting,setInteracting]=useState(false);
 const [reduceMotion,setReduceMotion]=useState(false);
 const viewportRef=useRef<HTMLDivElement>(null);
 const trackRef=useRef<HTMLDivElement>(null);
 const active=((position-count)%count+count)%count;

 useEffect(()=>{
  const media=window.matchMedia('(prefers-reduced-motion: reduce)');
  const update=()=>setReduceMotion(media.matches);
  update();
  media.addEventListener('change',update);
  return ()=>media.removeEventListener('change',update);
 },[]);

 useEffect(()=>{
  const viewport=viewportRef.current;
  const track=trackRef.current;
  if(!viewport||!track||!count)return;
  const measure=()=>{
   const cards=track.querySelectorAll<HTMLElement>('.bs-audience-slide');
   if(cards.length>=2){
    const distance=cards[1].offsetLeft-cards[0].offsetLeft;
    if(distance>0)setStep(distance);
   }
  };
  measure();
  const observer=new ResizeObserver(measure);
  observer.observe(viewport);
  const frame=window.requestAnimationFrame(()=>setAnimate(true));
  return ()=>{observer.disconnect();window.cancelAnimationFrame(frame);};
 },[count]);

 const next=useCallback(()=>{setAnimate(true);setPosition(current=>current+1);},[]);
 const previous=useCallback(()=>{setAnimate(true);setPosition(current=>current-1);},[]);

 useEffect(()=>{
  if(count<2||interacting||reduceMotion||step===0)return;
  const timer=window.setInterval(next,5600);
  return ()=>window.clearInterval(timer);
 },[count,interacting,reduceMotion,step,next,position]);

 const handleTransitionEnd=(event:React.TransitionEvent<HTMLDivElement>)=>{
  if(event.target!==event.currentTarget||event.propertyName!=='transform')return;
  if(position<count||position>=count*2){
   const normalized=count+((position%count)+count)%count;
   setAnimate(false);
   setPosition(normalized);
   window.requestAnimationFrame(()=>window.requestAnimationFrame(()=>setAnimate(true)));
  }
 };
 if(!count)return null;

 return <section
  className="bs-v5-section bs-audience-carousel-section"
  aria-label={title}
  onPointerEnter={()=>setInteracting(true)}
  onPointerLeave={()=>setInteracting(false)}
  onFocusCapture={()=>setInteracting(true)}
  onBlurCapture={event=>{if(!event.currentTarget.contains(event.relatedTarget as Node|null))setInteracting(false);}}
 >
  <div className="bs-shell">
   <div className="bs-audience-carousel-heading">
    <SectionHeading title={title} kicker={kicker} as="div" className="bs-audience-title-block"/>
    <div className="bs-audience-controls">
     <button type="button" onClick={previous} aria-label="Previous audience" className="bs-audience-arrow"><ChevronLeft size={21}/></button>
     <button type="button" onClick={next} aria-label="Next audience" className="bs-audience-arrow"><ChevronRight size={21}/></button>
    </div>
   </div>
   <div className="bs-audience-viewport" ref={viewportRef}>
    <div
     className="bs-audience-track"
     ref={trackRef}
     aria-hidden="true"
     onTransitionEnd={handleTransitionEnd}
     style={{
      transform:step>0?`translate3d(-${position*step}px,0,0)`:'none',
      transition:animate&&!reduceMotion?'transform 520ms cubic-bezier(.2,.72,.2,1)':'none'
     }}
    >
     {[0,1,2].flatMap(copy=>items.map((item,index)=>
      <div className="bs-audience-slide" key={`${copy}-${index}`}>
       <IconCard title={item.title} icon={item.icon} description={item.description} className="bs-audience-icon-card"/>
      </div>
     ))}
    </div>
   </div>
   <div className="bs-audience-pagination" aria-label="Choose audience slide">
    {items.map((item,index)=><button
     type="button"
     key={item.title}
     aria-label={`Show ${item.title}`}
     aria-current={active===index?'true':undefined}
     className={`bs-audience-dot${active===index?' is-active':''}`}
     onClick={()=>{setAnimate(true);setPosition(count+index);}}
    />)}
   </div>
   <ul className="bs-audience-screen-reader-list">
    {items.map(item=><li key={item.title}><strong>{item.title}:</strong> {item.description}</li>)}
   </ul>
  </div>
 </section>;
}

'use client';
import {useState,type FormEvent} from 'react';
import {Icon} from './Icon';
import {siteConfig} from '@/lib/site-data';
const interests=['MT5 White Label','MT5 Grey Label','MT4 White Label','CRM','Website','Liquidity','Hosting','Turnkey','API','Other'];
const stages=['Planning','Preparing to Launch','Existing Broker','Scaling'];
export function ContactForm(){
 const [pending,setPending]=useState(false);
 const [result,setResult]=useState<{ok:boolean;message:string}|null>(null);
 async function send(event:FormEvent<HTMLFormElement>){
  event.preventDefault();setPending(true);setResult(null);
  const form=event.currentTarget;const body=new FormData(form);
  if(process.env.NEXT_PUBLIC_STATIC_EXPORT==='true'){
   setResult({ok:false,message:'This is the GitHub Pages preview, so no message was submitted. Please use the live contact form on forextrade.pincodeit.com.'});
   setPending(false);
   return;
  }
  try{
   const response=await fetch('/api/contact',{method:'POST',body});
   const data=await response.json();
   setResult({ok:response.ok,message:data.message||(response.ok?'Message sent.':'Your request could not be sent.')});
   if(response.ok)form.reset();
  }catch{setResult({ok:false,message:'Unable to submit your request. Please try again later.'});}
  finally{setPending(false);}
 }
 return <div className="bs-contact-grid"><div className="bs-contact-intro">
   <span className="bs-eyebrow">REQUEST A CONSULTATION</span>
   <h2>Let&apos;s build something <em>reliable.</em></h2>
   <p>Planning a launch, fixing your existing setup, or deciding which technology you need? Tell us about your business and we&apos;ll arrange a useful technical consultation.</p>
   <p>No sales script and no obligation. Fields marked with an asterisk are required.</p>
   {siteConfig.site.email?<a href={`mailto:${siteConfig.site.email}`}>{siteConfig.site.email}<Icon name="arrowUpRight" size={17}/></a>:<a href={`${siteConfig.site.url}/contact`}>Open live contact form<Icon name="arrowUpRight" size={17}/></a>}
  </div>
  <form className="bs-contact-form" onSubmit={send}>
   <input type="text" name="website" autoComplete="off" tabIndex={-1} className="bs-honeypot" aria-hidden="true"/>
   <div className="bs-form-fields">
    <label><span>Name *</span><input autoComplete="name" type="text" name="name" placeholder="Your full name" required minLength={2} maxLength={100}/></label>
    <label><span>Business Email *</span><input autoComplete="email" type="email" name="email" placeholder="you@company.com" required maxLength={150}/></label>
    <label><span>Company</span><input autoComplete="organization" type="text" name="company" placeholder="Company name" maxLength={150}/></label>
    <label><span>Country</span><input autoComplete="country-name" type="text" name="country" placeholder="Country" maxLength={100}/></label>
    <label><span>Phone / WhatsApp</span><input autoComplete="tel" type="tel" name="contact" placeholder="Country code and number" maxLength={100}/></label>
    <label><span>What are you interested in?</span><select name="interest" defaultValue=""><option value="">Select a solution</option>{interests.map(option=><option key={option} value={option}>{option}</option>)}</select></label>
    <label className="wide"><span>Where is your business right now?</span><select name="stage" defaultValue=""><option value="">Select your current stage</option>{stages.map(option=><option key={option} value={option}>{option}</option>)}</select></label>
    <label className="wide"><span>Message *</span><textarea name="message" minLength={10} maxLength={4000} rows={6} required placeholder="Share your business model, target markets, current platform, providers you've already chosen, or the problem you're trying to solve."/></label>
   </div>
   <div className="bs-form-footer"><span>We&apos;ll use these details only to respond to your enquiry. We do not provide brokerage or investment services.</span><button className="bs-btn bs-btn-primary" type="submit" disabled={pending}>{pending?'Sending…':'Request a Consultation'}<Icon name="arrowUpRight" size={17}/></button></div>
   {result&&<p role="status" className={`bs-form-status ${result.ok?'success':'error'}`}>{result.message} {!result.ok&&process.env.NEXT_PUBLIC_STATIC_EXPORT==='true'&&<a href={`${siteConfig.site.url}/contact`}>Open the production contact form</a>}</p>}
  </form>
 </div>;
}

import {IconCard} from './IconCard';
import {SectionHeading} from './SectionHeading';

export type FeatureFlexItem={title:string;description:string;icon:string};

type Props={
 id:string;
 title:string;
 items:FeatureFlexItem[];
 intro?:string[];
 variant:'infrastructure'|'benefits';
};

export function FeatureFlexSection({id,title,items,intro=[],variant}:Props){
 const dark=variant==='benefits';
 return <section
  id={id}
  className={`bs-v5-section bs-feature-flex-section bs-feature-flex-${variant}`}
  aria-labelledby={`${id}-heading`}
 >
  <div className="bs-shell">
   <SectionHeading
    id={`${id}-heading`}
    title={title}
    className="bs-feature-flex-heading"
   >
    {intro.length>0&&<div className="bs-feature-flex-intro">{intro.map((paragraph,index)=><p key={index}>{paragraph}</p>)}</div>}
   </SectionHeading>
   <div className="bs-feature-flex-list">
    {items.map(item=><IconCard
      className={`bs-feature-flex-card ${dark?'bs-benefit-card':'bs-infrastructure-card'}`}
      title={item.title}
      icon={item.icon}
      description={item.description}
      key={item.title}
    />)}
   </div>
  </div>
 </section>;
}

'use client';
import {useEffect,useState,useRef} from 'react';
import Link from 'next/link';
import Image from 'next/image';
import {canonicalHref,getImage,type SlideData} from '@/lib/site-data';
import {Icon} from './Icon';

export function HomeSlider({slides,intervalMs=6000,autoplay=true}:{slides:SlideData[];intervalMs?:number;autoplay?:boolean}){
 const [index,setIndex]=useState(0),[paused,setPaused]=useState(false);
 const focusInside=useRef(false);
 useEffect(()=>{
  if(!autoplay||paused||slides.length<2)return;
  const media=window.matchMedia('(prefers-reduced-motion: reduce)');
  if(media.matches)return;
  const timer=window.setInterval(()=>setIndex(i=>(i+1)%slides.length),Math.max(3000,intervalMs));
  return ()=>window.clearInterval(timer);
 },[autoplay,paused,intervalMs,slides.length]);
 const previous=()=>setIndex(i=>(i-1+slides.length)%slides.length);
 const next=()=>setIndex(i=>(i+1)%slides.length);
 if(!slides.length)return null;
 return <section className="bs-home-slider" aria-label="Featured brokerage solutions" aria-roledescription="carousel"
  onMouseEnter={()=>setPaused(true)} onMouseLeave={()=>{if(!focusInside.current)setPaused(false)}}
  onFocusCapture={()=>{focusInside.current=true;setPaused(true)}} onBlurCapture={e=>{if(!e.currentTarget.contains(e.relatedTarget)){focusInside.current=false;setPaused(false)}}}
  onKeyDown={e=>{if(e.key==='ArrowLeft'){e.preventDefault();previous()}else if(e.key==='ArrowRight'){e.preventDefault();next()}}}>
  {slides.map((slide,i)=>{
   const image=getImage(slide.imageKey),active=i===index;
   return <div className={`bs-slide ${active?'is-active':''}`} key={slide.imageKey}
    role="group" aria-roledescription="slide" aria-label={`Slide ${i+1} of ${slides.length}`}
    aria-hidden={!active} inert={!active}>
    {image&&<Image src={image.url} alt={image.alt} fill priority={i===0} unoptimized sizes="100vw" className="bs-slide-photo"/>}
    <div className="bs-slide-shade"/>
    <div className="bs-shell bs-slide-copy">
     <div className="bs-slide-content">
      <span className="bs-slide-kicker">{slide.kicker||'FOREX TRADE TECHNOLOGY'}</span>
      {i===0?<h1>{slide.title}</h1>:<h2>{slide.title}</h2>}
      {slide.subtitle&&<p>{slide.subtitle}</p>}
      {slide.cta&&<Link href={canonicalHref(slide.cta.href)} className="bs-btn bs-btn-primary">{slide.cta.label}<Icon name="arrowUpRight" size={17}/></Link>}
     </div>
    </div>
   </div>;
  })}
  <div className="bs-slide-controls">
   <div className="bs-slide-dots" role="group" aria-label="Choose slide">{slides.map((slide,i)=><button type="button" key={slide.imageKey} aria-label={`Go to slide ${i+1}`} aria-current={i===index?'true':undefined} className={i===index?'is-active':''} onClick={()=>setIndex(i)}/>)}</div>
  </div>
 </section>;
}

import { ArrowUpRight,ArrowRight,ArrowUp,Check,ChevronLeft,ChevronRight,ChevronDown,Layers3,Link2,Menu,X,MessageCircle,Server,Settings2,ShieldCheck,Users,Zap,Wallet,Building2,Globe2,Headphones,Shield,Database, type LucideProps } from 'lucide-react';
const icons:Record<string,React.ComponentType<LucideProps>>={
 arrowUpRight:ArrowUpRight,'arrow-up-right':ArrowUpRight,arrowUp:ArrowUp,'arrow-up':ArrowUp,arrowRight:ArrowRight,
 check:Check,'check-circle':Check,chevronDown:ChevronDown,chevronLeft:ChevronLeft,chevronRight:ChevronRight,layers:Layers3,link:Link2,menu:Menu,x:X,message:MessageCircle,server:Server,
 settings:Settings2,shield:ShieldCheck,'shield-check':ShieldCheck,users:Users,zap:Zap,payments:Wallet,building:Building2,
 globe:Globe2,support:Headphones,database:Database,security:Shield
};
export function Icon({name,className,size=19,...props}:LucideProps & {name?:string}){
 const Component=icons[name||'']||ArrowUpRight;
 return <Component aria-hidden="true" size={size} className={className} strokeWidth={1.9} {...props}/>;
}

import type {ReactNode} from 'react';
import {Icon} from './Icon';

type IconCardProps={
 title?:string;
 icon:string;
 description?:string;
 paragraphs?:readonly string[];
 children?:ReactNode;
 className?:string;
};

/** Decorative background icon — never read out twice by screen readers. */
export function IconWatermark({icon}:{icon:string}){
 return <span className="bs-icon-card-watermark" aria-hidden="true"><Icon name={icon} size={146}/></span>;
}

/**
 * Canonical icon-box component.
 * Pass icon + title + description/paragraphs; layout contexts may supply
 * extra class names, but do not redefine typography or badge colors.
 */
export function IconCard({title,icon,description,paragraphs,children,className=''}:IconCardProps){
 return <article className={`bs-icon-card bs-ui-card ${className}`.trim()}>
  <IconWatermark icon={icon}/>
  <div className="bs-icon-card-header">
   <span className="bs-icon-card-badge" aria-hidden="true"><Icon name={icon} size={22}/></span>
  </div>
  {title&&<h3 className="bs-ui-card-title">{title}</h3>}
  <div className="bs-icon-card-copy bs-ui-card-copy">
   {description&&<p>{description}</p>}
   {paragraphs?.map((paragraph,index)=><p key={index}>{paragraph}</p>)}
   {children}
  </div>
 </article>;
}

import Link from 'next/link';
import Image from 'next/image';
import {canonicalHref,getImage,type PageData} from '@/lib/site-data';
import {SectionHeading} from './SectionHeading';
export function PageHeader({page}:{page:PageData}){
 const top=page.pageTop,image=getImage(top?.backgroundImageKey||page.hero.imageKey);
 // Some v3 JSON subtitles contain source-document breadcrumb labels; never present those as marketing copy.
 const raw=(top?.subtitle||'').trim();
 const fallback=page.hero.leadParagraphs?.find(text=>text.trim()&&!/^(Breadcrumb|Label):/i.test(text.trim()))||page.hero.subtitle||'';
 const subtitle=/^(Breadcrumb|Label):/i.test(raw)?fallback:raw;
 return <section className="bs-page-header" aria-labelledby="bs-page-heading" data-view-transition={top?.viewTransition||'hero'}>
  {image&&<Image className="bs-page-bg" src={image.url} alt={image.alt} fill priority unoptimized sizes="100vw"/>}
  <div className="bs-page-header-overlay"/>
  <div className="bs-shell bs-page-header-content">
   <nav className="bs-breadcrumb" aria-label="Breadcrumb">{(top?.breadcrumbs||[{label:'Home',href:'/'},{label:top?.title||page.hero.title}]).map((crumb,i,arr)=><span key={`${crumb.label}-${i}`} className="bs-crumb">{i>0&&<span aria-hidden="true" className="bs-crumb-slash">/</span>}{crumb.href&&i<arr.length-1?<Link href={canonicalHref(crumb.href)}>{crumb.label}</Link>:<span aria-current={i===arr.length-1?'page':undefined}>{crumb.label}</span>}</span>)}</nav>
   <SectionHeading
    as="div" level="h1" id="bs-page-heading"
    kicker={top?.kicker||page.hero.kicker||'FOREX TRADE TECHNOLOGY'}
    title={top?.title||page.hero.title}
    subtitle={subtitle}
    className="bs-page-heading"
    kickerClassName="bs-hero-kicker"
    titleClassName="bs-page-title"
    subtitleClassName="bs-page-subtitle"
   />
  </div>
 </section>;
}

import Link from 'next/link';
import Image from 'next/image';
import {Fragment} from 'react';
import {canonicalHref,getImage,type ContentBlock,type FaqItem,type PageData,type SectionData} from '@/lib/site-data';
import {Icon} from './Icon';
import {ContactForm} from './ContactForm';
import {HomeSlider} from './HomeSlider';
import {TrustCarousel} from './TrustCarousel';
import {AudienceCarousel} from './AudienceCarousel';
import {IconCard} from './IconCard';
import {SectionHeading} from './SectionHeading';
import {FeatureFlexSection} from './FeatureFlexSection';
import {VisualStorySection} from './VisualStorySection';
import {PageHeader} from './PageHeader';
import {FinalCTA} from './FinalCTA';
import {TradingStackFlow} from './TradingStackFlow';

type Group={heading:string|null;paragraphs:string[]};
function regroup(blocks:ContentBlock[]):Group[]{
 const groups:Group[]=[];
 for(const block of blocks){
  if(block.type==='h3'){groups.push({heading:block.text,paragraphs:[]});continue;}
  if(block.type==='h2')continue; // H2 already rendered by the containing section.
  if(block.type==='p'){
   if(!groups.length||groups[groups.length-1].heading===null&&groups[groups.length-1].paragraphs.length===0){
    if(!groups.length)groups.push({heading:null,paragraphs:[]});
   }
   groups[groups.length-1].paragraphs.push(block.text);
  }
 }
 return groups;
}
function Trust({section}:{section:SectionData}){
 const items=(section.items||[]).filter((item):item is string=>typeof item==='string');
 return <TrustCarousel items={items}/>;
}
function TextParagraphs({paragraphs}:{paragraphs:string[]}){return <>{paragraphs.map((p,i)=><p key={i}>{p}</p>)}</>}
function DenseFaq({section}:{section:SectionData}){
 const items=(section.items||[]).filter((x):x is FaqItem=>typeof x!=='string'&&'q'in x);
 return <section className="bs-section bs-dense-section bs-dense-faq-page bs-faq-polished" id={section.id} aria-labelledby="faq-questions-heading"><div className="bs-shell">
  <SectionHeading className="bs-dense-heading bs-faq-heading" kicker="SUPPORT & GUIDANCE" title="Frequently Asked Questions" id="faq-questions-heading"><p className="bs-faq-count"><strong>{items.length}</strong><span>questions answered</span></p></SectionHeading>
  <div className="bs-dense-accordion bs-clean-accordion bs-faq-questions">{items.map((item,i)=><details key={i} name="ftt-faq"><summary><span className="bs-faq-question">{item.q}</span><Icon name="chevronDown" size={19}/></summary><div className="bs-dense-answer bs-faq-answer"><p>{item.a}</p></div></details>)}</div>
 </div></section>;
}

/** The layout key is authoritative in v5; section.type only describes source semantics. */
function V5EditableBlocks({blocks}:{blocks:ContentBlock[]}){
 return <div className="bs-v5-copy">{blocks.map((block,i)=>block.type==='h3'?<h3 key={i}>{block.text}</h3>:block.type==='h2'?<h3 key={i}>{block.text}</h3>:<p key={i}>{block.text}</p>)}</div>;
}
function V5SectionContent({section,index,pageId}:{section:SectionData;index:number;pageId:string}){
 const groups=regroup(section.blocks||[]);
 const leads=groups.filter(x=>!x.heading).flatMap(x=>x.paragraphs);
 const topics=groups.filter(x=>x.heading);
 const layout=section.layout||'stack';
 const dark=layout==='darkBand';
 if(layout==='splitContent'&&section.title==='Request a Consultation')
  return <section className="bs-v5-section bs-v5-contact" id={section.id}><div className="bs-shell"><h2>{section.title}</h2><ContactForm/></div></section>;
 // Prose-only and text-only bands should never leave half the desktop canvas empty.
 // Use alternating editorial content and relevant, content-derived visual diagrams.
 if(layout==='stack'||(layout==='darkBand'&&topics.length===0)||(layout==='timeline'&&topics.length===0)){
  return <VisualStorySection section={section} pageId={pageId} index={index} dark={layout==='darkBand'}/>;
 }
 let cards=topics.map((g,i)=>({title:g.heading||'',paragraphs:g.paragraphs,order:i}));
 if(layout.startsWith('cardGrid')&&cards.length===0&&leads.length>1){
   cards=leads.map((para,i)=>({title:'',paragraphs:[para],order:i}));
 }
 const leadContent=(layout.startsWith('cardGrid')||layout==='timeline')&&topics.length===0&&leads.length>1?[]:leads;
 const headerSubtitle=leadContent[0];
 return <section id={section.id} className={'bs-v5-section bs-v5-layout-'+layout+(dark?' bs-v5-dark':'')+(index%2&&!dark?' bs-v5-soft':'')} data-view-transition={section.viewTransition||'section'}>
  <div className="bs-shell">
   <SectionHeading className="bs-v5-section-heading" title={section.title} subtitle={headerSubtitle}/>
   {leadContent.length>1&&<div className="bs-v5-intro">{leadContent.slice(1).map((p,i)=><p key={i}>{p}</p>)}</div>}
   {layout.startsWith('cardGrid')&&cards.length>0&&<div className={'bs-v5-grid '+(layout==='cardGrid2'?'bs-v5-grid-two':'bs-v5-grid-three')}>{cards.map((c,i)=>
    <IconCard className="bs-v5-card" key={i} title={c.title} icon={['layers','server','shield','link','users','payments'][i%6]} paragraphs={c.paragraphs}/>)}</div>}
   {layout==='timeline'&&<div className="bs-v5-steps">{(topics.length?topics:leads.length>=2?leads.map((p,i)=>({heading:'Step '+(i+1),paragraphs:[p]})):[]).map((g,i)=>
    <IconCard key={i} className="bs-v5-card bs-step-card" title={g.heading||''} icon={['check','settings','server','link','shield'][i%5]} paragraphs={g.paragraphs}/>)}</div>}
   {layout==='stack'&&topics.length>0&&<div className="bs-v5-prose-list">{topics.map((g,i)=><article key={i}><h3>{g.heading}</h3><TextParagraphs paragraphs={g.paragraphs}/></article>)}</div>}
   {dark&&topics.length>0&&<div className="bs-v5-dark-list">{topics.map((g,i)=><IconCard key={i} className="bs-v5-card bs-dark-feature-card" title={g.heading||''} icon={['server','layers','link','shield','support'][i%5]} paragraphs={g.paragraphs}/>)}</div>}
  </div>
 </section>;
}
/** Split page titles into a white lead and mild lime emphasis without changing their text. */
function mediaTitleParts(title:string):[string,string]{
 const clean=title.trim();
 if(clean==='Forex Trade Technology')return ['Forex Trade','Technology'];
 const ampersand=clean.indexOf(' & ');
 const forClause=clean.toLowerCase().indexOf(' for ');
 const boundary=ampersand>=0?ampersand:forClause;
 if(boundary>7)return [clean.slice(0,boundary),clean.slice(boundary+1)];
 const words=clean.split(' ').filter(Boolean);
 const pivot=Math.max(1,Math.ceil(words.length*.56));
 return [words.slice(0,pivot).join(' '),words.slice(pivot).join(' ')];
}
function V5MediaBand({section,title}:{section:SectionData;title:string}){
 const img=getImage(section.media?.imageKey);if(!img)return null;
 const [primary,accent]=mediaTitleParts(title);
 const headingId=`${section.id}-heading`;
 return <section id={section.id} className="bs-v5-media bs-v5-media-title-band" aria-labelledby={headingId}>
  <Image src={img.url} alt="" fill unoptimized loading="lazy" sizes="100vw" className="bs-v5-media-photo"/>
  <div className="bs-v5-media-shade" aria-hidden="true"/>
  <div className="bs-shell bs-v5-media-caption">
   <div className="bs-v5-media-title-content">
    <span className="bs-v5-media-eyebrow">FOREX TRADE TECHNOLOGY</span>
    <h2 id={headingId} className="bs-v5-media-title">{primary}{accent&&<> <span>{accent}</span></>}</h2>
   </div>
  </div>
 </section>;
}
function V5Gallery({section}:{section:SectionData}){
 const keys=section.media?.imageKeys||[];
 return <section id={section.id} className="bs-v5-section bs-v5-gallery"><div className="bs-shell">
  <SectionHeading className="bs-v5-section-heading" kicker="TECHNOLOGY IN PRACTICE" title={section.title==='Who We Work With'?'Technology Behind the Brokerage':section.title}/>
  <div className="bs-v5-gallery-grid">{keys.map(key=>{const img=getImage(key);return img?<figure key={key}><div className="bs-v5-gallery-photo"><Image src={img.url} alt={img.alt} fill unoptimized loading="lazy" sizes="(max-width:700px) 95vw, 33vw"/></div><figcaption>{img.alt}</figcaption></figure>:null})}</div>
 </div></section>;
}
/** All fullBlocks are retained in source JSON; this includes material omitted by the v5 layout shortlist. */
function getSupplementalContent(page:PageData){
 const used=new Map<string,number>();
 for(const sec of page.sections)for(const b of sec.blocks||[]){const key=b.type+'\u0000'+b.text;used.set(key,(used.get(key)||0)+1);}
 const result:Array<{title:string;blocks:ContentBlock[]}>=[];
 let active:{title:string;blocks:ContentBlock[]}={title:'Introduction and overview',blocks:[]};
 const push=()=>{if(active.blocks.length)result.push(active);};
 for(const b of page.fullBlocks||[]){
  // Source document outline labels belong in the actual header, not the visible guide.
  if(/^(?:breadcrumb|label):\s/i.test(b.text.trim()))continue;
  if(b.type==='h2'){push();active={title:b.text,blocks:[]};continue;}
  const key=b.type+'\u0000'+b.text,remaining=used.get(key)||0;
  if(remaining>0){used.set(key,remaining-1);continue;}
  active.blocks.push(b);
 }
 push();return result;
}
function V5Guide({page}:{page:PageData}){
 const groups=getSupplementalContent(page);if(!groups.length)return null;
 return <section className="bs-v5-guide bs-v5-section" id="complete-technical-guide" aria-labelledby="complete-guide-title"><div className="bs-shell">
  <SectionHeading className="bs-v5-guide-head" kicker="IN-DEPTH TECHNICAL GUIDE" title="Further details and frequently asked questions" id="complete-guide-title" subtitle="Complete supporting explanations, implementation considerations and FAQs from our original service guide."/>
  <div className="bs-v5-guide-grid bs-clean-accordion">{groups.map((group,i)=><details key={i} className="bs-v5-guide-item" name="ftt-guide"><summary><span>{group.title}</span><Icon name="chevronDown" size={20}/></summary><V5EditableBlocks blocks={group.blocks}/></details>)}</div>
 </div></section>;
}

function Section({section,index,pageTitle,pageId}:{section:SectionData;index:number;pageTitle:string;pageId:string}){
 if(pageId==='home'&&section.title==='How Your Trading Stack Connects')return <TradingStackFlow section={section}/>;
 if(section.title==='Platform & Infrastructure Under One Roof'||section.title==='Why Brokers Work With Us'){
  const topics=regroup(section.blocks||[]);
  const icons=section.title==='Why Brokers Work With Us'
   ? ['server','layers','link','shield','support']
   : ['settings','server','database','link','users'];
  const items=topics.filter(group=>group.heading).map((group,i)=>({
   title:group.heading||'',
   description:group.paragraphs.join(' '),
   icon:icons[i%icons.length]
  }));
  const intro=topics.filter(group=>!group.heading).flatMap(group=>group.paragraphs);
  return <FeatureFlexSection
   id={section.id}
   title={section.title}
   items={items}
   intro={intro}
   variant={section.title==='Why Brokers Work With Us'?'benefits':'infrastructure'}
  />;
 }
 if(section.title==='Who We Work With'&&section.blocks?.some(block=>block.type==='h3')){
  const icons=['building','server','users','settings'];
  const items=regroup(section.blocks).filter(group=>group.heading).map((group,i)=>({
   title:group.heading||'',
   description:group.paragraphs.join(' '),
   icon:icons[i%icons.length]
  }));
  return <AudienceCarousel title={section.title} items={items}/>;
 }
 if(section.layout==='iconRow')return <Trust section={section}/>;
 if(section.layout==='mediaBand')return <V5MediaBand section={section} title={pageTitle}/>;
 if(section.layout==='gallery3')return <V5Gallery section={section}/>;
 if(section.layout==='faqAccordion')return <DenseFaq section={section}/>;
 return <V5SectionContent section={section} index={index} pageId={pageId}/>;
}
function Notes({notes}:{notes?:string[]}){if(!notes?.length)return null;return <aside className="bs-notes"><div className="bs-shell"><details><summary>Additional information and risk disclosure</summary>{notes.map((note,i)=><p key={i}>{note}</p>)}</details></div></aside>}
export function PageRenderer({page}:{page:PageData}){
 const top=page.pageTop;
 const pageTitle=page.slug==='/'?'Forex Trade Technology':top?.title||page.hero.title;
 // Image-backed promotional title bands are exclusive to the homepage.
 // Interior routes retain PageHeader with their own H1, breadcrumbs and introduction.
 const isHome=page.slug==='/';
 const visibleSections=page.sections.filter(section=>section.layout!=='ctaBand'&&(isHome||section.layout!=='mediaBand'));
 return <main id="main-content" className="bs-main bs-v4-dense bs-v5 bs-clean-page">
  {top?.variant==='homeSlider'&&top.slides?.length ? <HomeSlider slides={top.slides} intervalMs={top.intervalMs} autoplay={top.autoplay}/> : <PageHeader page={page}/>}
  {visibleSections.map((section,index)=><Fragment key={section.id}>
   <Section section={section} index={index} pageTitle={pageTitle} pageId={page.id}/>
  </Fragment>)}
  <V5Guide page={page}/>
  <Notes notes={page.documentFooterNotes}/>
  <FinalCTA home={isHome}/>
 </main>;
}

'use client';
import {useEffect,useMemo,useRef,useState,type FormEvent,type KeyboardEvent} from 'react';
import {usePathname} from 'next/navigation';
import {Icon} from './Icon';

const staticPreview=process.env.NEXT_PUBLIC_STATIC_EXPORT==='true';
const issueBase='https://github.com/omarreact/Forex-Trade-Technology-Omar/issues/new';
const categories=['Design / spacing','Typography / colors','Content correction','Mobile / responsive','Navigation / interaction','Other'];
type Status={ok:boolean;text:string};

export function ReviewFeedback(){
 const path=usePathname();
 const [open,setOpen]=useState(false);
 const [sending,setSending]=useState(false);
 const [status,setStatus]=useState<Status|null>(null);
 const [sections,setSections]=useState<Array<{id:string;label:string}>>([]);
 const [name,setName]=useState('');
 const [email,setEmail]=useState('');
 const [message,setMessage]=useState('');
 const [category,setCategory]=useState(categories[0]);
 const [section,setSection]=useState('');
 const [honeypot,setHoneypot]=useState('');
 const buttonRef=useRef<HTMLButtonElement>(null);
 const dialogRef=useRef<HTMLDivElement>(null);

 useEffect(()=>{
  if(!open)return;
  setSections([...document.querySelectorAll<HTMLElement>('main section[id]')].map(el=>({
   id:el.id,label:el.querySelector('h2,h3')?.textContent?.trim()?.slice(0,85)||el.id
  })));
  dialogRef.current?.querySelector<HTMLButtonElement>('.bs-review-close')?.focus({preventScroll:true});
  const keyDown=(ev:globalThis.KeyboardEvent)=>{
   if(ev.key==='Escape'){setOpen(false);buttonRef.current?.focus({preventScroll:true});}
  };
  document.addEventListener('keydown',keyDown);
  const previousOverflow=document.body.style.overflow;
  document.body.style.overflow='hidden';
  return()=>{document.removeEventListener('keydown',keyDown);document.body.style.overflow=previousOverflow;};
 },[open,path]);

 const issueURL=useMemo(()=>{
  const title='Website feedback: '+category+' — '+path;
  // Do NOT include reviewer name/email in publicly readable GitHub issues.
  const body=['## Page',path,'','## Section',section||'General / entire page',
    '','## Issue type',category,'','## Requested change',message.trim()||'(Add details here)',
    '','---','Submitted from the Forex Trade Technology review widget. No private contact information included.'
  ].join('\n');
  return issueBase+'?'+new URLSearchParams({title,body}).toString();
 },[path,section,category,message]);

 function close(){setOpen(false);buttonRef.current?.focus({preventScroll:true});}
 function onKey(event:KeyboardEvent<HTMLDivElement>){
  if(event.key!=='Tab')return;
  const focusables=[...(dialogRef.current?.querySelectorAll<HTMLElement>(
   'button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]'
  )||[])].filter(el=>el.getClientRects().length>0&&el.tabIndex>=0);
  if(!focusables.length)return;
  if(event.shiftKey&&document.activeElement===focusables[0]){
   event.preventDefault();focusables[focusables.length-1].focus();
  }else if(!event.shiftKey&&document.activeElement===focusables[focusables.length-1]){
   event.preventDefault();focusables[0].focus();
  }
 }

 async function submit(event:FormEvent<HTMLFormElement>){
  event.preventDefault();
  setStatus(null);
  if(staticPreview){
   window.open(issueURL,'_blank','noopener,noreferrer');
   setStatus({ok:false,text:'A GitHub issue draft was requested. If it did not open, use the link below. Sign in and click Submit new issue to post your feedback.'});
   return;
  }
  setSending(true);
  const form=new FormData();
  form.set('kind','website-feedback');
  form.set('name',name.trim());form.set('email',email.trim());
  form.set('message',message.trim());form.set('category',category);
  form.set('section',section);form.set('pageUrl',window.location.href);
  form.set('website',honeypot);
  try{
   const response=await fetch('/api/contact',{method:'POST',body:form,headers:{Accept:'application/json'}});
   const data=await response.json() as {ok?:boolean;message?:string};
   if(response.ok&&data.ok){
    setStatus({ok:true,text:'Your feedback was accepted by the email service.'});
    setMessage('');
   }else{
    setStatus({ok:false,text:data.message||'Email submission failed. You can report a public GitHub issue below.'});
   }
  }catch{
   setStatus({ok:false,text:'Email delivery is currently unavailable. You can report a public GitHub issue below.'});
  }finally{setSending(false);}
 }

 return <>
  <button ref={buttonRef} type="button" className="bs-review-trigger"
   aria-label="Suggest a website change" aria-haspopup="dialog" aria-expanded={open}
   onClick={()=>{setOpen(true);setStatus(null)}}>
   <Icon name="message" size={20}/><span>Suggest a change</span>
  </button>
  {open&&<div className="bs-review-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}>
   <div ref={dialogRef} className="bs-review-dialog" role="dialog" aria-modal="true"
    aria-labelledby="bs-review-title" aria-describedby="bs-review-description" onKeyDown={onKey}>
    <header className="bs-review-head">
     <div><span className="bs-review-kicker">DEVELOPMENT FEEDBACK</span>
      <h2 id="bs-review-title">Suggest a change</h2></div>
     <button type="button" className="bs-review-close" aria-label="Close feedback form" onClick={close}>
      <Icon name="x" size={20}/>
     </button>
    </header>
    <div className="bs-review-body">
     <p id="bs-review-description" className="bs-review-desc">
      {staticPreview?'Report a website issue directly to the GitHub repository.':
       'Describe a design or content change for the website team.'}
     </p>
     {staticPreview&&<p className="bs-review-privacy">
      <Icon name="info" size={17}/> GitHub issues are public. Do not include passwords, private emails or personal details.
     </p>}
     <form id="bs-review-form" className="bs-review-form" onSubmit={submit}>
      <label className="bs-review-honeypot" aria-hidden="true">
       Leave blank<input value={honeypot} tabIndex={-1} onChange={e=>setHoneypot(e.target.value)} autoComplete="off"/>
      </label>
      {!staticPreview&&<div className="bs-review-two">
       <label>Your name<input name="name" autoComplete="name" value={name}
        onChange={e=>setName(e.target.value)} minLength={2} maxLength={100} required placeholder="Name"/></label>
       <label>Email for reply<input name="email" autoComplete="email" type="email" value={email}
        onChange={e=>setEmail(e.target.value)} maxLength={150} required placeholder="you@example.com"/></label>
      </div>}
      <div className="bs-review-two">
       <label>Page<input readOnly value={path} aria-label="Current website page"/></label>
       <label>Section<select value={section} onChange={e=>setSection(e.target.value)}>
        <option value="">Entire page</option>{sections.map(x=><option value={x.id} key={x.id}>{x.label}</option>)}
       </select></label>
      </div>
      <label>Issue type<select value={category} onChange={e=>setCategory(e.target.value)}>
       {categories.map(x=><option key={x}>{x}</option>)}
      </select></label>
      <label>What should change?
       <textarea value={message} onChange={e=>setMessage(e.target.value)}
        minLength={10} maxLength={staticPreview?1800:4000} rows={4} required
        placeholder="Describe the problem and how it should look or behave."/>
      </label>
     </form>
    </div>
    <footer className="bs-review-footer">
     {status&&<p role="status" className={`bs-review-status ${status.ok?'success':'warning'}`}>{status.text}</p>}
     {((staticPreview&&status)||(!staticPreview&&status&&!status.ok))&&<a
      className="bs-review-issue-link" href={issueURL} target="_blank" rel="noopener noreferrer">
      Review draft on GitHub <Icon name="arrowUpRight" size={17}/>
     </a>}
     <button form="bs-review-form" className="bs-review-submit" type="submit" disabled={sending}>
      {sending?'Sending…':staticPreview?'Review on GitHub':'Send feedback'} <Icon name="arrowRight" size={18}/>
     </button>
     <p className="bs-review-note">{staticPreview
      ?'Feedback is posted only after you confirm on GitHub. A GitHub account is required.'
      :'Email sending requires a configured provider. Failed requests are not marked as delivered.'}</p>
    </footer>
   </div>
  </div>}
 </>;
}

'use client';
import {useEffect,useState} from 'react';
import {Icon} from './Icon';
import {siteConfig} from '@/lib/site-data';
export function ScrollToTop(){
 const [visible,setVisible]=useState(false);
 useEffect(()=>{const update=()=>setVisible(window.scrollY>=siteConfig.features.scrollToTop.threshold);update();window.addEventListener('scroll',update,{passive:true});return()=>window.removeEventListener('scroll',update);},[]);
 if(!siteConfig.features.scrollToTop.enabled) return null;
 return <button type="button" onClick={()=>window.scrollTo({top:0,behavior:'smooth'})} className={`bs-scroll-top ${visible?'visible':''}`} aria-label={siteConfig.features.scrollToTop.label} title={siteConfig.features.scrollToTop.label}><Icon name="arrowUp" size={21}/></button>;
}

import type {ReactNode} from 'react';

type Props={
 title?:string;
 kicker?:string;
 subtitle?:string;
 children?:ReactNode;
 id?:string;
 level?:'h1'|'h2';
 as?:'div'|'header';
 className?:string;
 titleClassName?:string;
 kickerClassName?:string;
 subtitleClassName?:string;
};

/**
 * Shared, semantic title block. Copy and optional kicker/subtitle come from
 * each section; typography is controlled only by component-system.css.
 * Keep a single page H1; sections default to H2.
 */
export function SectionHeading({
 title,kicker='FOREX TRADE TECHNOLOGY',subtitle,children,id,
 level='h2',as='header',className='',titleClassName='',
 kickerClassName='',subtitleClassName=''
}:Props){
 const Wrapper=as;
 const Heading=level;
 return <Wrapper className={`bs-ui-heading ${className}`.trim()}>
  {kicker&&<span className={`bs-ui-kicker ${kickerClassName}`.trim()}>{kicker}</span>}
  <Heading id={id} className={`bs-ui-title ${titleClassName}`.trim()}>{title}</Heading>
  {subtitle&&<p className={`bs-ui-lead ${subtitleClassName}`.trim()}>{subtitle}</p>}
  {children}
 </Wrapper>;
}

import Link from 'next/link';
import {canonicalHref,siteConfig} from '@/lib/site-data';
