export function SiteFooter(){return <footer className="bs-footer">
 <div className="bs-shell bs-footer-main">
  <div className="bs-footer-about"><Link href="/" className="bs-footer-logo">Forex Trade <strong>Technology<span>.</span></strong></Link><p>{siteConfig.footer.brand.description}</p>{siteConfig.site.email?<a href={`mailto:${siteConfig.site.email}`} className="bs-footer-email">{siteConfig.site.email}<Icon name="arrowUpRight" size={17}/></a>:<Link href={canonicalHref("/contact")} className="bs-footer-email">Contact our team<Icon name="arrowUpRight" size={17}/></Link>}</div>
  {siteConfig.footer.columns.map(c=><div className="bs-footer-col" key={c.heading}><h3>{c.heading}</h3>{c.links.map(l=><Link href={canonicalHref(l.href)} key={l.href}>{l.label}</Link>)}</div>)}
 </div><div className="bs-shell bs-footer-bottom"><span>{siteConfig.site.copyright}</span><Link href={canonicalHref('/contact')}>Talk to our team <Icon name="arrowUpRight" size={15}/></Link></div>
 </footer>}

'use client';
import Link from 'next/link';
import {usePathname} from 'next/navigation';
import {useEffect,useRef,useState} from 'react';
import {Icon} from './Icon';
import {canonicalHref,siteConfig} from '@/lib/site-data';

export function SiteHeader(){
 const [menu,setMenu]=useState(false);
 const [submenu,setSubmenu]=useState(false);
 const headerRef=useRef<HTMLElement>(null);
 const dropdownRef=useRef<HTMLDivElement>(null);
 const pathname=usePathname();
 const isCurrent=(href:string)=>{
  const normalize=(value:string)=>value.replace(/\/+$/,'')||'/';
  return normalize(pathname)===normalize(canonicalHref(href));
 };

 useEffect(()=>{setMenu(false);setSubmenu(false)},[pathname]);
 useEffect(()=>{
  const closeOnOutside=(event:PointerEvent)=>{
   if(!headerRef.current?.contains(event.target as Node)){setMenu(false);setSubmenu(false)}
   else if(!dropdownRef.current?.contains(event.target as Node)){setSubmenu(false)}
  };
  const closeOnEscape=(event:KeyboardEvent)=>{
   if(event.key==='Escape'){setSubmenu(false);setMenu(false)}
  };
  document.addEventListener('pointerdown',closeOnOutside);
  document.addEventListener('keydown',closeOnEscape);
  return ()=>{
   document.removeEventListener('pointerdown',closeOnOutside);
   document.removeEventListener('keydown',closeOnEscape);
  };
 },[]);

 return <header className="bs-site-header bs-clean-header" ref={headerRef}>
   <div className="bs-shell bs-header-inner">
    <Link href="/" className="bs-brand" aria-label={`${siteConfig.site.name} — Home`}>
      <span className="bs-brand-mark" aria-hidden="true">✳</span><span className="bs-logo-text">FOREX<span>TRADE</span><small>TECHNOLOGY</small></span>
    </Link>
    <button type="button" className="bs-mobile-menu-toggle" aria-controls="bs-primary-nav" aria-label={menu?'Close navigation':'Open navigation'} aria-expanded={menu} onClick={()=>{setMenu(v=>!v);setSubmenu(false)}}><Icon name={menu?'x':'menu'} size={25}/></button>
    <nav id="bs-primary-nav" aria-label="Main navigation" className={`bs-inline-nav ${menu?'is-open':''}`}>
     {siteConfig.navigation.primary.map(nav=>('children' in nav && Array.isArray(nav.children))?
        <div className="bs-nav-dropdown" key={nav.id} ref={dropdownRef}>
         <button className={`bs-nav-link bs-menu-trigger ${nav.children.some(child=>isCurrent(child.href))?'active':''}`} aria-expanded={submenu} aria-haspopup="true" aria-controls="bs-solutions" type="button" onClick={()=>setSubmenu(v=>!v)}>
          {nav.label}<Icon name="chevronDown" size={14}/>
         </button>
         <div id="bs-solutions" className={`bs-submenu ${submenu?'is-open':''}`} aria-hidden={!submenu}>
          {nav.children.map(child=><Link tabIndex={submenu?0:-1} key={child.id} href={canonicalHref(child.href)} aria-current={isCurrent(child.href)?'page':undefined} className={isCurrent(child.href)?'active':''}>{child.label}<Icon name="arrowUpRight" size={16}/></Link>)}
         </div>
        </div>
      :<Link href={canonicalHref(('href' in nav && typeof nav.href==='string')?nav.href:'/')} key={nav.id} className={`bs-nav-link ${pathname.replace(/\/$/,'')===canonicalHref(('href' in nav && typeof nav.href==='string')?nav.href:'/').replace(/\/$/,'')?'active':''}`}>{nav.label}</Link>)}
      <Link className="bs-btn bs-btn-primary bs-nav-cta" href={canonicalHref(siteConfig.navigation.cta.href)}>{siteConfig.navigation.cta.label}<Icon name="arrowUpRight" size={16}/></Link>
    </nav>
    <Link className="bs-btn bs-btn-primary bs-desktop-cta" href={canonicalHref(siteConfig.navigation.cta.href)}>{siteConfig.navigation.cta.label}<Icon name="arrowUpRight" size={16}/></Link>
   </div>
  </header>;
}

import {Icon} from './Icon';
import {SectionHeading} from './SectionHeading';
import type {SectionData} from '@/lib/site-data';

const connections=[
 {label:'Client trade',sub:'Order request',icon:'users'},
 {label:'MT4 / MT5',sub:'Trading platform',icon:'server'},
 {label:'Bridge / FIX',sub:'Gateway connection',icon:'link'},
 {label:'Liquidity',sub:'Price & execution',icon:'globe'},
 {label:'CRM & reporting',sub:'Trade record',icon:'database'}
] as const;

/**
 * Replaces three mostly-empty icon boxes with one legible relationship diagram.
 * Original supporting copy is preserved below the flow (section.blocks).
 */
export function TradingStackFlow({section}:{section:SectionData}){
 const copy=(section.blocks||[]).filter(b=>b.type==='p').map(b=>b.text);
 return <section id={section.id} className="bs-stack-flow-section bs-v5-section" aria-labelledby="bs-stack-flow-heading">
  <div className="bs-shell">
   <SectionHeading id="bs-stack-flow-heading" title={section.title}
    subtitle={copy[0]||'Follow a trade from the client to execution and reporting.'}/>
   <div className="bs-stack-flow-panel">
    <div className="bs-stack-flow-panel-top">
     <span>ONE CONNECTED TRADING STACK</span>
     <span className="bs-stack-flow-emphasis"><Icon name="check" size={15}/> Configuration · Testing · Monitoring</span>
    </div>
    <ol className="bs-stack-flow-steps" aria-label="Trading and reporting system connections">
     {connections.map((step,i)=><li key={step.label} className="bs-stack-flow-item">
      <div className="bs-stack-flow-node">
       <span className="bs-stack-flow-node-icon"><Icon name={step.icon} size={25}/></span>
       <strong>{step.label}</strong>
       <span>{step.sub}</span>
      </div>
      {i<connections.length-1&&<span className="bs-stack-flow-arrow" aria-hidden="true"><Icon name="arrowRight" size={20}/></span>}
     </li>)}
    </ol>
    <p className="bs-stack-flow-caption">Connected trade lifecycle — each integration must be configured, tested and monitored.</p>
   </div>
   {copy.length>1&&<div className="bs-stack-flow-explanation">
    <div className="bs-stack-flow-prose"><p>{copy[1]}</p></div>
    {copy[2]&&<aside className="bs-stack-flow-conclusion"><Icon name="shield" size={22}/><p>{copy[2]}</p></aside>}
   </div>}
  </div>
 </section>;
}

'use client';

import {Icon} from './Icon';

type TrustCarouselProps={items:string[]};

/**
 * Edge-to-edge looping capabilities ticker. Six equal groups make the
 * one-group translation seamless even across ultrawide viewports.
 * Repeated items are hidden from assistive technology.
 */
export function TrustCarousel({items}:TrustCarouselProps){
 if(!items.length)return null;
 return <section className="bs-trust bs-trust-carousel" aria-label="Technology that connects">
  <div className="bs-trust-carousel-window" aria-live="off">
   <div className="bs-trust-carousel-track">
    {Array.from({length:6},(_,copy)=>
     <div className="bs-trust-carousel-group" key={copy} aria-hidden={copy>0}>
      {items.map((item,index)=>
       <span className="bs-trust-carousel-item" key={`${index}-${item}`}>
        <Icon name="check" size={18}/>
        <span>{item}</span>
       </span>
      )}
     </div>
    )}
   </div>
  </div>
 </section>;
}

import Image from 'next/image';
import {getImage,type ContentBlock,type SectionData} from '@/lib/site-data';
import {Icon} from './Icon';
import {SectionHeading} from './SectionHeading';

type StoryVisual={image:string;eyebrow:string;nodes:[string,string,string];icons:[string,string,string]};
const stories:Record<string,StoryVisual>={
 'brokerage-setup':{image:'meeting',eyebrow:'BROKERAGE LAUNCH',nodes:['Planning','Trading platform','Connected operations'],icons:['check','server','link']},
 'mt5-white-label':{image:'trading_desk',eyebrow:'YOUR BRANDED ENVIRONMENT',nodes:['Branded terminals','MT5 groups','Liquidity link'],icons:['layers','settings','link']},
 hosting:{image:'data_center',eyebrow:'TRADING INFRASTRUCTURE',nodes:['Trade servers','Active monitoring','Recovery planning'],icons:['server','shield','database']},
 liquidity:{image:'network',eyebrow:'EXECUTION CONNECTIVITY',nodes:['Trading platform','Bridge / FIX','Liquidity providers'],icons:['server','link','globe']},
 crm:{image:'crm_team',eyebrow:'CONNECTED CLIENT LIFECYCLE',nodes:['Onboarding','CRM & KYC','MT5 accounts'],icons:['users','shield','server']},
 'kyc-aml':{image:'identity',eyebrow:'VERIFICATION WORKFLOW',nodes:['Client documents','Verification','Review history'],icons:['users','shield','database']},
 payments:{image:'payments',eyebrow:'PAYMENT OPERATIONS',nodes:['Client portal','Provider status','Reconciliation'],icons:['users','link','database']},
 'prop-firm':{image:'prop_desk',eyebrow:'PROP TRADING OPERATIONS',nodes:['Challenges','Rule monitoring','Progression'],icons:['layers','shield','check']},
 'how-it-works':{image:'checklist',eyebrow:'DELIVERY PROCESS',nodes:['Consultation','Integration','Launch support'],icons:['users','settings','support']},
 about:{image:'collaboration',eyebrow:'HOW WE WORK',nodes:['Understand','Connect','Support'],icons:['users','link','support']},
 contact:{image:'contact_desk',eyebrow:'START A CONVERSATION',nodes:['Your enquiry','Technical review','Next steps'],icons:['message','server','check']},
 home:{image:'network',eyebrow:'CONNECTED TECHNOLOGY',nodes:['Platform','Operations','Liquidity'],icons:['server','layers','link']},
 faq:{image:'support',eyebrow:'BROKERAGE GUIDANCE',nodes:['Find answers','Review options','Talk to us'],icons:['message','check','support']}
};

type Props={section:SectionData;pageId:string;index:number;dark?:boolean};
export function VisualStorySection({section,pageId,index,dark=false}:Props){
 const info=stories[pageId]||stories.home;
 const visual=getImage(info.image);
 const blocks=section.blocks||[];
 const groupItems:Array<{title:string;paragraphs:string[]}>= [];
 const leads:string[]=[];
 for(const block of blocks){
  if(block.type==='h3'){groupItems.push({title:block.text,paragraphs:[]});continue;}
  if(block.type==='p'){
   if(groupItems.length)groupItems[groupItems.length-1].paragraphs.push(block.text);
   else leads.push(block.text);
  }
 }
 const listItems=leads.filter(p=>/^\*\s/.test(p.trim()));
 const narrative=leads.filter(p=>!/^\*\s/.test(p.trim()));
 const reverse=index%2===0;
 return <section id={section.id} className={`bs-v5-section bs-story-section ${dark?'bs-story-dark':index%2?'bs-story-tint':'bs-story-light'} ${reverse?'bs-story-reverse':''}`} aria-labelledby={`${section.id}-title`}>
  <div className="bs-shell bs-story-shell">
   <div className="bs-story-copy">
    <SectionHeading id={`${section.id}-title`} title={section.title} className="bs-story-heading"/>
    {narrative.length>0&&<div className="bs-story-prose">{narrative.map((p,i)=><p key={i}>{p}</p>)}</div>}
    {listItems.length>0&&<ul className="bs-story-checklist">{listItems.map((p,i)=><li key={i}><Icon name="check" size={18}/><span>{p.trim().replace(/^\*\s*/, '')}</span></li>)}</ul>}
    {groupItems.length>0&&<div className="bs-story-details">{groupItems.map((g,i)=>
     <article key={g.title}><span className="bs-story-detail-icon"><Icon name={info.icons[i%3]} size={20}/></span>
      <div><h3>{g.title}</h3>{g.paragraphs.map((p,j)=><p key={j}>{p}</p>)}</div>
     </article>
    )}</div>}
   </div>
   <div className="bs-story-visual">
    {visual&&<Image src={visual.url} alt="" fill unoptimized loading="lazy" sizes="(max-width: 820px) 95vw, 48vw" className="bs-story-photo"/>}
    <div className="bs-story-gradient" aria-hidden="true"/>
    <div className="bs-story-diagram">
     <span className="bs-story-diagram-label">{info.eyebrow}</span>
     <div className="bs-story-nodes">
      {info.nodes.map((label,i)=><div className="bs-story-node" key={label}>
       <span className="bs-story-node-icon"><Icon name={info.icons[i]} size={19}/></span>
       <span>{label}</span>
      </div>)}
     </div>
     <div className="bs-story-diagram-bottom"><span className="bs-story-live-dot"/>Integrated technology workflow</div>
    </div>
   </div>
  </div>
 </section>;
}
